238	    /**
239	     * The owner's membership level, a number from 1 to 4 derived from the
240	     * owner's own fields. Starts at {@code 1}, gains {@code 1} when a contact
241	     * email is on file, gains {@code 1} when the owner has no namesakes, gains
242	     * {@code 1} when the owner's {@link #getTenureDays() tenure} exceeds
243	     * {@value #TENURE_DAYS_FOR_LEVEL_4} days, and is capped at {@code 4}. Because
244	     * a newly created owner has zero tenure, a new owner never exceeds level 3.
245	     */
246	    public Integer getMembershipLevel() {
247	        int level = 1;
248	        boolean hasEmail = this.email != null && !this.email.isEmpty();
249	        if (hasEmail) {
250	            level += 1;
251	        }
252	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
253	        if (noNamesakes) {
254	            level += 1;
255	        }
256	        Long tenureDays = getTenureDays();
257	        if (tenureDays != null && tenureDays > TENURE_DAYS_FOR_LEVEL_4) {
258	            level += 1;
259	        }
260	        return Math.min(level, 4);
261	    }
