263	    /**
264	     * The owner's tenure: the number of whole days from the {@link #registrationDate}
265	     * to the server's current date, or {@code null} when no registration date is on
266	     * file. Never negative for a registration date that is today or earlier.
267	     */
268	    public Long getTenureDays() {
269	        if (this.registrationDate == null) {
270	            return null;
271	        }
272	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
273	    }
