363	    /**
364	     * Return the Pet with the given name, or null if none found for this Owner.
365	     *
366	     * @param name to test
367	     * @return true if pet name is already in use
368	     */
369	    public Pet getPet(String name) {
370	        return getPet(name, false);
371	    }
372	
373	    /**
374	     * Return the Pet with the given name, or null if none found for this Owner.
375	     *
376	     * @param name to test
377	     * @return true if pet name is already in use
378	     */
379	    public Pet getPet(String name, boolean ignoreNew) {
380	        name = name.toLowerCase();
381	        for (Pet pet : getPetsInternal()) {
382	            if (!ignoreNew || !pet.isNew()) {
383	                String compName = pet.getName();
384	                compName = compName.toLowerCase();
385	                if (compName.equals(name)) {
386	                    return pet;
387	                }
388	            }
389	        }
390	        return null;
391	    }
392	
393	    public Pet getPet(Integer petId) {
394	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
395	    }
